// Owner B. Routes: 'cards.list', 'cards.generate', 'cardItems.patch' (PLAN_M2 3.4, D22). The card logic is
// study/paperCards.ts; the run (repair, terminal writes) is llm/runManager.ts.
// cards.generate: request id first (rule 1a) → paper (404) and readiness (409) → runTask with the `generating` card
// row as start row (409 card_generating when a card of the kind is being generated by another request id).
// The run is a background task (cancelOnDisconnect=false): it keeps running when the stream is dropped.
import { eq } from 'drizzle-orm';
import { paperCardItems, paperCards, papers } from '../db/schema';
import { HttpError, notFound, routeBody, routeJson, routeParams, type RouteModule } from '../deps';
import { PROMPT_VERSION } from '../llm/runManager';
import { CARD_TASK, cardIdentity, listCards, startCardRows, toCardItemDto } from '../study/paperCards';
import { streamRun } from './threads';

export const paperCardsRoutes: RouteModule = (deps) => ({
  'cards.list': (c) => {
    const { id: paperId } = routeParams(c, 'cards.list');
    const paper = deps.db.select({ deletingAt: papers.deletingAt }).from(papers).where(eq(papers.id, paperId)).get();
    if (!paper || paper.deletingAt !== null) throw notFound('paper');
    return routeJson(c, 'cards.list', { cards: listCards(deps.db, paperId) });
  },

  'cards.generate': async (c) => {
    const { id: paperId, kind } = routeParams(c, 'cards.generate');
    const body = await routeBody(c, 'cards.generate');
    const task = CARD_TASK[kind];
    const identity = cardIdentity(paperId, kind);
    const existing = deps.runs.findExisting({ clientRequestId: body.clientRequestId, paperId, identity });
    if (existing) return streamRun(c, existing, task);
    const paper = deps.db.select({ contextReadyAt: papers.contextReadyAt, deletingAt: papers.deletingAt }).from(papers).where(eq(papers.id, paperId)).get();
    if (!paper || paper.deletingAt !== null) throw notFound('paper');
    if (paper.contextReadyAt === null) throw new HttpError(409, 'context_not_ready', 'paper context is not ready yet');
    const handle = deps.runTask({ task, clientRequestId: body.clientRequestId, paperId, inputs: {}, identity, startRows: startCardRows(paperId, kind, PROMPT_VERSION) });
    return streamRun(c, handle, task);
  },

  'cardItems.patch': async (c) => {
    const { id } = routeParams(c, 'cardItems.patch');
    const body = await routeBody(c, 'cardItems.patch');
    const row = deps.db
      .select({ status: paperCards.status, deletingAt: papers.deletingAt })
      .from(paperCardItems)
      .innerJoin(paperCards, eq(paperCards.id, paperCardItems.cardId))
      .innerJoin(papers, eq(papers.id, paperCards.paperId))
      .where(eq(paperCardItems.id, id))
      .get();
    if (!row || row.deletingAt !== null) throw notFound('card item');
    if (body.confirmed === undefined && body.userNote === undefined) throw new HttpError(400, 'validation', 'nothing to change (confirmed or userNote)');
    deps.db
      .update(paperCardItems)
      .set({ ...(body.confirmed !== undefined ? { confirmed: body.confirmed } : {}), ...(body.userNote !== undefined ? { userNote: body.userNote } : {}) })
      .where(eq(paperCardItems.id, id))
      .run();
    return routeJson(c, 'cardItems.patch', toCardItemDto(deps.db, deps.db.select().from(paperCardItems).where(eq(paperCardItems.id, id)).get()!));
  },
});
